      "ar": "فَلَمَّا رَءَا الشَّمْسَ بَازِغَةً قَالَ هَٰذَا رَبِّي هَٰذَا أَكْبَرُ فَلَمَّا أَفَلَتْ قَالَ يَٰقَوْمِ إِنِّي بَرِيءٌ مِّمَّا تُشْرِكُونَ",
