      "numero": 107,
      "ar": "وَلَوْ شَاءَ اللَّهُ مَا أَشْرَكُواْ وَمَا جَعَلْنَٰكَ عَلَيْهِمْ حَفِيظًا وَمَا أَنتَ عَلَيْهِم بِوَكِيلٍ",
